    """Return True if the jail itself or any descendant is still a mountpoint."""
    if os.path.ismount(jailPath):
        return True
    for root, dirs, _ in os.walk(jailPath):
        for name in dirs:
            if os.path.ismount(os.path.join(root, name)):
                return True
    return False

